export function getSvmgovProgramErrorMessage(code: SvmgovProgramError): string {
  if (process.env["NODE_ENV"] !== "production") {
    return (svmgovProgramErrorMessages as Record<SvmgovProgramError, string>)[
      code
    ];
  }

  return "Error message not available in production bundles.";
}

export function isSvmgovProgramError<
  TProgramErrorCode extends SvmgovProgramError,
>(
  error: unknown,
  transactionMessage: {
    instructions: Record<number, { programAddress: Address }>;
  },
  code?: TProgramErrorCode,
): error is SolanaError<typeof SOLANA_ERROR__INSTRUCTION_ERROR__CUSTOM> &
  Readonly<{ context: Readonly<{ code: TProgramErrorCode }> }> {
  return isProgramError<TProgramErrorCode>(
    error,
    transactionMessage,
    SVMGOV_PROGRAM_PROGRAM_ADDRESS,
    code,
  );
}
